rows[38236]={title={{14,382559613},"불 뿜는 토템"},description={"^summons a searing totem with ([%+%-]?%d[%d,.%+%-to –]*) health at your feet for ([%+%-]?%d[%d,.]* %a+) that repeatedly attacks an enemy within 40 yards for ([%+%-]?%d[%d,.%+%-to –]*) fire damage%.$","시전자의 위치에 \0311\031의 생명력을 지닌 불타는 토템을 소환하여 지속적으로 주위 40미터 반경 내의 적을 공격하여 \0313\031의 화염 피해를 입히게 합니다. \0312\031 동안 지속됩니다.",{0,1,0},{1,2,3}}}
