rows[38617]={title={{17,1327082338},"냉기의 무기 공격"},description={"^imbue the shaman's weapon with frost%. each hit has a chance of causing ([%+%-]?%d[%d,.%+%-to –]*) additional frost damage and slowing the target's movement speed by ([%+%-]?%d[%d,.%+%-to –]*)%% for ([%+%-]?%d[%d,.]* %a+)%. lasts 30 minutes%.$","주술사의 무기에 얼음의 기운을 부여합니다. 주문이 지속되는 동안 주술사의 무기는 매번 공격 시 일정 확률로 \0311\031의 추가 냉기 피해를 입히고 \0313\031 동안 대상의 이동 속도를 \0312\031%만큼 감소시킵니다. 30분 동안 지속됩니다.",{0,0,1},{1,2,3}},aura={"^movement slowed to ([%+%-]?%d[%d,.%+%-to –]*)%% of normal speed%.$","이동 속도 평소의 \0311\031%로 감소",{0},{1}}}
