rows[41469]={title={{15,2092039147},"지휘의 문장"},description={"^gives the caster a chance to deal additional holy damage equal to ([%+%-]?%d[%d,.%+%-to –]*)%% of normal weapon damage%. lasts ([%+%-]?%d[%d,.]* %a+)%. judging this command deals ([%+%-]?%d[%d,.%+%-to –]*) holy damage%.$","\0312\031 동안 성기사를 지휘의 기운으로 감싸 일정 확률로 무기 공격력의 \0311\031%에 해당하는 추가 신성 피해를 입힙니다.\010\010문장의 에너지를 폭발시키면 즉시 해당 적에게 \0313\031의 신성 피해를 입힙니다.",{0,1,0},{1,2,3}},aura={{59,2003900419},"근접 공격 시 일정 확률로 추가 신성 피해"}}
rows[41470]={title={{19,366578940},"지휘의 심판"},description={"^judges the enemy for ([%+%-]?%d[%d,.%+%-to –]*) holy damage%.$","적을 심판하여 \0311\031의 신성 피해를 입힙니다.",{0},{1}}}
rows[41471]={title={{15,777863635},"강화된 일격"},description={"^smites an enemy, inflicting ([%+%-]?%d[%d,.%+%-to –]*) holy damage%.$","적을 강타하여 \0311\031의 신성 피해를 입힙니다.",{0},{1}}}
rows[41472]={title={{12,846092292},"신성한 격노"},description={"^consumes an enemy in flames, burning it and inflicting additional fire damage every ([%+%-]?%d[%d,.%+%-to –]*) sec%. over ([%+%-]?%d[%d,.]* %a+)%.$","신성한 불꽃으로 적을 집어삼켜 화염 피해를 입히고 추가로 \0312\031에 걸쳐 \0311\031초마다 추가 화염 피해를 입힙니다.",{0,1},{1,2}},aura={"^([%+%-]?%d[%d,.%+%-to –]*) holy damage inflicted every ([%+%-]?%d[%d,.%+%-to –]*) sec%.$","\0312\031초마다 \0311\031의 신성 피해",{0,0},{1,2}}}
