rows[41475]={title={{17,305004202},"반사의 보호막"},description={"^wraps the caster in a shield that lasts up to ([%+%-]?%d[%d,.]* %a+)%., absorbing a maximum of ([%+%-]?%d[%d,.%+%-to –]*) damage and reflecting half of any absorbed damage back onto the attacker%.$","\0311\031 동안 시전자를 보호막으로 감싸 최대 \0312\031의 물리 피해를 흡수하고 흡수된 피해의 반에 해당하는 피해를 공격자에게 되돌립니다.",{1,0},{1,2}},aura={{110,295252609},"물리 및 마법 공격 보호\010흡수된 피해의 절반만큼 공격자에게 반사"}}
