rows[41478]={title={{12,856707996},"마법 감쇠"},description={"^dampens magic used against the targeted party member, decreasing damage taken from spells by up to ([%+%-]?%d[%d,.%+%-to –]*)%% and healing spells by up to ([%+%-]?%d[%d,.%+%-to –]*)%. lasts ([%+%-]?%d[%d,.]* %a+)%.$","대상 파티원에게 미치는 마법의 위력을 감쇠시켜 마법 공격으로 받는 피해를 최대 \0311\031%만큼 감소시키지만, 치유 주문에 의한 회복량이 최대 \0312\031만큼 감소합니다. \0313\031 동안 지속됩니다.",{0,0,1},{1,2,3}},aura={"^reduces magic damage taken by up to ([%+%-]?%d[%d,.%+%-to –]*)%% and healing by up to ([%+%-]?%d[%d,.%+%-to –]*)%.$","받는 마법 피해 최대 \0311\031%만큼 감소\010생명력 회복량 최대 \0312\031만큼 감소",{0,0},{1,2}}}
