rows[41607]={title={{26,970389662},"샤트라스의 증강"},description={"^increases the player's maximum health by ([%+%-]?%d[%d,.%+%-to –]*) and dodge by ([%+%-]?%d[%d,.%+%-to –]*) for ([%+%-]?%d[%d,.]* %a+)%. counts as both a battle and guardian elixir%. this effect persists through death%.$","\0313\031 동안 최대 생명력이 \0311\031만큼 증가하고 회피가 \0312\031만큼 증가합니다. 동시에 전투 비약 및 강화 비약으로 간주됩니다. 이 효과는 죽어도 지속됩니다.",{0,0,1},{1,2,3}},aura={"^increases health by ([%+%-]?%d[%d,.%+%-to –]*) and dodge by ([%+%-]?%d[%d,.%+%-to –]*)%.$","생명력 \0311\031만큼 증가\010회피 \0312\031만큼 증가",{0,0},{1,2}}}
rows[41608]={title={{31,1839723666},"샤트라스의 가혹한 공격"},description={"^increases attack power by ([%+%-]?%d[%d,.%+%-to –]*) for ([%+%-]?%d[%d,.]* %a+)%. counts as both a battle and guardian elixir%. this effect persists through death%. only active in tempest keep, serpentshrine cavern, caverns of time: mount hyjal, black temple and the sunwell plateau%.$","\0312\031 동안 전투력이 \0311\031만큼 증가합니다. 동시에 전투 비약 및 강화 비약으로 간주됩니다. 이 효과는 죽어도 지속됩니다.\010\010폭풍우 요새, 불뱀 제단, 시간의 동굴: 하이잘 산, 검은 사원, 태양샘 고원에서만 효과를 발휘합니다.",{0,1},{1,2}},aura={"^attack power increased by ([%+%-]?%d[%d,.%+%-to –]*)%. only active in tempest keep, serpentshrine cavern, caverns of time: mount hyjal, black temple and the sunwell plateau%.$","전투력 \0311\031만큼 증가\010\010폭풍우 요새, 불뱀 제단, 시간의 동굴: 하이잘 산, 검은 사원, 태양샘 고원에서만 효과 발휘",{0},{1}}}
rows[41609]={title={{26,970389662},"샤트라스의 증강"},description={"^increases maximum health by ([%+%-]?%d[%d,.%+%-to –]*) and dodge by 10 for ([%+%-]?%d[%d,.]* %a+)%. counts as both a battle and guardian elixir%. this effect persists through death%. only active in tempest keep, serpentshrine cavern, caverns of time: mount hyjal, black temple and the sunwell plateau%.$","\0312\031 동안 최대 생명력이 \0311\031만큼 증가하고 회피가 10만큼 증가합니다. 동시에 전투 비약 및 강화 비약으로 간주됩니다. 이 효과는 죽어도 지속됩니다.\010\010폭풍우 요새, 불뱀 제단, 시간의 동굴: 하이잘 산, 검은 사원, 태양샘 고원에서만 효과를 발휘합니다.",{0,1},{1,2}},aura={"^increases health by ([%+%-]?%d[%d,.%+%-to –]*) and dodge by 10%. only active in tempest keep, serpentshrine cavern, caverns of time: mount hyjal, black temple and the sunwell plateau%.$","생명력 \0311\031만큼 증가\010회피 10만큼 증가\010\010폭풍우 요새, 불뱀 제단, 시간의 동굴: 하이잘 산, 검은 사원, 태양샘 고원에서만 효과 발휘",{0},{1}}}
